import{_ as a,C as r,o,c as h,aj as e,E as n}from"./framework.js";const _=JSON.parse('{"title":"控制台：续费 | Product / Console | Documentation","description":"控制台：续费 in Kooboo: 续费页不直接完成支付，它负责找到需要处理的续费项，并把你带到域名续费弹窗或会员页。","frontmatter":{"title":"控制台：续费 | Product / Console | Documentation","description":"控制台：续费 in Kooboo: 续费页不直接完成支付，它负责找到需要处理的续费项，并把你带到域名续费弹窗或会员页。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/console/renewals.html"}]]},"headers":[],"relativePath":"zh/product/console/renewals.md","filePath":"product/console/renewals.md","lastUpdated":1781010536000}'),l={name:"zh/product/console/renewals.md"};function i(s,t,c,b,p,m){const d=r("DocImage");return o(),h("div",null,[t[0]||(t[0]=e('<h1 id="控制台-续费" tabindex="-1">控制台：续费 <a class="header-anchor" href="#控制台-续费" aria-label="Permalink to &quot;控制台：续费&quot;">​</a></h1><blockquote><p>汇总当前组织需要续费的域名和会员项目，按类型筛选并进入对应续费流程。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>顶部 <strong>控制台</strong> -&gt; 左侧 <strong>续费</strong></td></tr><tr><td>深链</td><td><code>/_Admin/kconsole/renew</code></td></tr><tr><td>前端路由</td><td><code>/kconsole/renew</code></td></tr><tr><td>可见身份</td><td>组织管理员</td></tr></tbody></table><p>续费页不直接完成支付，它负责找到需要处理的续费项，并把你带到域名续费弹窗或会员页。</p>',5)),n(d,{src:"/product/console/renewals-overview.png",alt:"控制台续费列表（金额与域名已脱敏）",width:"1120"}),t[1]||(t[1]=e('<h2 id="筛选标签" tabindex="-1">筛选标签 <a class="header-anchor" href="#筛选标签" aria-label="Permalink to &quot;筛选标签&quot;">​</a></h2><p>表格左上方提供筛选标签：</p><table tabindex="0"><thead><tr><th>标签</th><th>说明</th></tr></thead><tbody><tr><td>All</td><td>显示全部续费项</td></tr><tr><td>Domain Renew</td><td>只显示域名</td></tr><tr><td>Membership Renew</td><td>只显示会员</td></tr></tbody></table><p>前端代码中保留了 Application 类型的处理，但当前常规标签只展示域名和会员。</p><h2 id="续费列表" tabindex="-1">续费列表 <a class="header-anchor" href="#续费列表" aria-label="Permalink to &quot;续费列表&quot;">​</a></h2><p>表格显示：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>Item</td><td>项目类型标签和名称</td></tr><tr><td>Status</td><td>正常或已过期</td></tr><tr><td>Expire Date</td><td>到期日期</td></tr><tr><td>Charge Period</td><td>计费周期，年或月</td></tr><tr><td>Renew Price</td><td>续费价格和币种</td></tr><tr><td>Renew Now</td><td>进入对应续费流程</td></tr></tbody></table><p>状态由 <code>expiredIn</code> 判断：到期时间早于当前时间时显示已过期，否则显示正常。</p><h2 id="域名续费" tabindex="-1">域名续费 <a class="header-anchor" href="#域名续费" aria-label="Permalink to &quot;域名续费&quot;">​</a></h2><p>域名续费项点击 <code>Renew Now</code> 后会打开域名续费弹窗。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>Domain</td><td>当前域名，只读</td></tr><tr><td>Period</td><td>续费年限，1 到 10 年</td></tr><tr><td>OK</td><td>创建域名续费订单</td></tr></tbody></table><p>确认后会跳转到 <a href="./orders.html#结账页">订单结账页</a>。</p><h2 id="会员续费" tabindex="-1">会员续费 <a class="header-anchor" href="#会员续费" aria-label="Permalink to &quot;会员续费&quot;">​</a></h2><p>会员续费项点击 <code>Renew Now</code> 后会跳转到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/kconsole/member</span></span></code></pre></div><p>在 <a href="./membership.html">会员</a> 页确认当前计划和套餐后，再创建会员续费订单。</p><h2 id="常见工作流" tabindex="-1">常见工作流 <a class="header-anchor" href="#常见工作流" aria-label="Permalink to &quot;常见工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>统一查看到期项</td><td>续费 -&gt; All</td></tr><tr><td>只处理域名</td><td>续费 -&gt; Domain Renew -&gt; Renew Now -&gt; 结账</td></tr><tr><td>只处理会员</td><td>续费 -&gt; Membership Renew -&gt; 会员页 -&gt; 结账</td></tr><tr><td>付款后复核</td><td>订单 -&gt; 续费 -&gt; 确认项目状态</td></tr></tbody></table><h2 id="与订单页的关系" tabindex="-1">与订单页的关系 <a class="header-anchor" href="#与订单页的关系" aria-label="Permalink to &quot;与订单页的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>续费页</th><th>订单页</th></tr></thead><tbody><tr><td>找到要续费的项目，并创建续费订单</td><td>查看订单是否支付、是否交付</td></tr><tr><td>面向“到期项”</td><td>面向“已创建订单”</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./../console.html">控制台概述</a></td><td>控制台菜单地图</td></tr><tr><td><a href="./domains.html">域名</a></td><td>域名管理与域名续费入口</td></tr><tr><td><a href="./membership.html">会员</a></td><td>会员续费入口</td></tr><tr><td><a href="./orders.html">订单</a></td><td>续费后的结账流程</td></tr></tbody></table>',22))])}const g=a(l,[["render",i]]);export{_ as __pageData,g as default};
